// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 victimDeposit, uint256 attackerDeposit) public {
        vm.assume(victimDeposit <= VALUE_CAP);
        vm.assume(attackerDeposit <= VALUE_CAP);
        victimDeposit = bound(victimDeposit, 1, 100 ether);
        attackerDeposit = bound(attackerDeposit, 1, 100 ether);

        Reenterer attacker = new Reenterer(c);
        vm.deal(address(attacker), attackerDeposit);
        vm.deal(address(0xBEEF), victimDeposit);

        vm.prank(address(0xBEEF));
        c.deposit{value: victimDeposit}();

        vm.prank(address(attacker));
        c.deposit{value: attackerDeposit}();

        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(address(attacker));
        try c.withdrawAll() {} catch {}

        uint256 withdrawn = contractBalanceBefore - address(c).balance;
        assertTrue(withdrawn <= attackerDeposit);
    }
}

contract Reenterer {
    ReentrancyDAO private c;
    bool private entered;

    constructor(ReentrancyDAO _c) {
        c = _c;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.withdrawAll();
        }
    }
}
